<?php declare(strict_types=1);
/** Genuine first numbering confirmations and an actually allocated number. */
function recoveryNumberingOriginal(PDO $db):array
{
    $db->exec("INSERT INTO clubs VALUES('own-number-recovery','Own numbering recovery');INSERT INTO actors(id,club_id,role,is_superuser)VALUES('own-number-recovery-admin','own-number-recovery','treasurer',0)");
    $settings=new \Kulturhus\Verein\Settings($db,'own-number-recovery-admin');$requests=new \Kulturhus\Verein\Settings\GeneralRequests($db,'own-number-recovery-admin');$originals=[];
    foreach([str_repeat('ß',20),'0']as$suffix){$state=$settings->section('numbers');$data=$state['data'];$data['invoice']['prefix']=str_repeat('ä',30);$data['invoice']['suffix']=$suffix;$data['invoice']['next']=max(100,$data['invoice']['next']);$input=['version'=>(string)$state['version'],'data'=>$data,'date'=>'2024-02-29'];$plan=$requests->prepare('numbers',$input);$requestKey=bin2hex(random_bytes(16));$originals[]=$requests->accept('numbers',$input,$requestKey,$plan['hash'],true);if(count($originals)===1){$db->beginTransaction();$assigned=\Kulturhus\Verein\Numbering::allocate($db,'own-number-recovery','invoice','2024-02-29','own-recovery-number-original');$db->commit();}}
    return['originals'=>$originals,'current'=>$settings->section('numbers'),'first_revision'=>$requests->revision('numbers','1'),'assigned'=>$assigned,'counter'=>(int)$db->query("SELECT next_number FROM number_counters WHERE club_id='own-number-recovery'AND kind='invoice'")->fetchColumn()];
}
